// This file is generated by AI.

// 资源浏览器: 浏览项目 game/ 下的资源 (排除 scene)。
// 布局: 顶部全宽工具栏 (返回上级/搜索/展平/文件管理器) + 左侧资源列表 + 右侧预览。
// 缩略图与媒体均通过预览服务器的 overlay 站点 URL 加载。

import { revealItemInDir } from '@tauri-apps/plugin-opener';
import { useEffect, useState } from 'react';

import { fs } from '../lib/fs';
import { sniffKind } from '../lib/sniff';
import { previewClient } from '../preview/client';
import { useAppStore } from '../state/store';
import { FileTree, type FileKind, type FileNode } from './FileTree';

export function ResourceBrowser() {
  const projectPath = useAppStore((s) => s.projectPath);
  const settings = useAppStore((s) => s.settings);
  const [assetBase, setAssetBase] = useState<string | null>(null);
  const [selected, setSelected] = useState<FileNode | null>(null);
  const [textPreview, setTextPreview] = useState<string | null>(null);
  const [detectedKind, setDetectedKind] = useState<FileKind | null>(null);

  // 确保预览服务器与 overlay 站点可用, 以构建资源 URL
  useEffect(() => {
    if (!projectPath) return;
    let cancelled = false;
    void previewClient.ensureSite(projectPath, settings.enginePath ?? undefined).then((url) => {
      if (!cancelled) setAssetBase(url);
    });
    return () => {
      cancelled = true;
    };
  }, [projectPath, settings.enginePath]);

  useEffect(() => {
    setSelected(null);
  }, [projectPath]);

  // 类型探测: 不只看扩展名, 对无法确定 (other) 或疑似误标 (text) 的文件读取文件头判断;
  // 仍无法识别时按文本文件处理 (用户要求: 未知文件当成文本)。
  useEffect(() => {
    setDetectedKind(null);
    if (!selected || (selected.kind !== 'other' && selected.kind !== 'text')) return;
    let cancelled = false;
    void fs
      .readHead(selected.path, 64)
      .then((head) => {
        if (cancelled) return;
        setDetectedKind(sniffKind(head) ?? 'text');
      })
      .catch(() => {
        if (!cancelled) setDetectedKind('text');
      });
    return () => {
      cancelled = true;
    };
  }, [selected]);

  // 实际预览类型: 探测结果优先
  const effectiveKind: FileKind | null = selected ? (detectedKind ?? selected.kind) : null;

  // 文本文件预览 (媒体直接走 URL; 用容错解码避免非法 UTF-8 抛错)
  useEffect(() => {
    setTextPreview(null);
    if (!selected || effectiveKind !== 'text') return;
    let cancelled = false;
    void fs
      .readTextLossy(selected.path)
      .then((text) => {
        if (!cancelled) setTextPreview(text.slice(0, 20000));
      })
      .catch(() => {});
    return () => {
      cancelled = true;
    };
  }, [selected, effectiveKind]);

  const assetUrl = (rel: string): string | undefined => {
    if (!assetBase) return undefined;
    return `${assetBase}game/${rel.split('/').map(encodeURIComponent).join('/')}`;
  };

  if (!projectPath) return <div className="resource-browser empty">未打开项目</div>;

  return (
    <div className="resource-browser">
      <FileTree
        rootPath={`${projectPath}\\game`}
        excludeTop={(name) => name === 'scene'}
        selectedPath={selected?.path ?? null}
        assetUrl={assetUrl}
        onRevealDir={(dir) => void revealItemInDir(dir)}
        onOpen={(file) => setSelected(file)}
        header={(toolbar, list) => (
          <>
            {toolbar}
            <div className="resource-body">
              <div className="resource-files">{list}</div>
              <div className="resource-preview">
                {selected ? (
                  effectiveKind === 'image' && assetUrl(selected.rel) ? (
                    <img src={assetUrl(selected.rel) ?? undefined} alt={selected.name} />
                  ) : effectiveKind === 'audio' && assetUrl(selected.rel) ? (
                    <audio src={assetUrl(selected.rel) ?? undefined} controls />
                  ) : effectiveKind === 'video' && assetUrl(selected.rel) ? (
                    <video src={assetUrl(selected.rel) ?? undefined} controls />
                  ) : effectiveKind === 'text' && textPreview !== null ? (
                    <pre>{textPreview}</pre>
                  ) : (
                    <span className="muted">该类型暂无预览</span>
                  )
                ) : (
                  <span className="muted">选择文件以预览</span>
                )}
              </div>
            </div>
          </>
        )}
      />
    </div>
  );
}
